// Roblox fan mockup + accounts API in one file. Cloudflare Workers + D1.
// The web page is embedded below as PAGE.
const enc = new TextEncoder();
const SESSION_SECONDS = 60 * 60 * 24 * 30;
const ITERATIONS = 100000; // Workers' maximum for PBKDF2

const cleanScripts = (a) => Array.isArray(a) ? a.slice(0, 20).map((s) => ({ name: String((s && s.name) || "Script").slice(0, 40), cls: String((s && s.cls) || "Script").slice(0, 30), source: String((s && s.source) || "").slice(0, 50000) })) : [];
const isAdm = (env, r) => r.is_admin === 1 || ["roblox", ...String((env && env.ADMIN_USERS) || "").split(",")].map((s) => s.trim().toLowerCase()).filter(Boolean).includes(String(r.username).toLowerCase());
const cleanInsts = (a) => Array.isArray(a) ? a.slice(0, 300).map((s) => ({ name: String((s && s.name) || "Object").slice(0, 40), cls: String((s && s.cls) || "Folder").slice(0, 40) })) : [];
const nn = (v) => Math.max(0, Math.floor(Number(v) || 0));
const hex = (buf) => [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
const fromHex = (s) => new Uint8Array(s.match(/../g).map((h) => parseInt(h, 16)));

async function hashPassword(password, saltBytes) {
  const key = await crypto.subtle.importKey("raw", enc.encode(password), "PBKDF2", false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits(
    { name: "PBKDF2", hash: "SHA-256", salt: saltBytes, iterations: ITERATIONS },
    key,
    256
  );
  return hex(bits);
}

async function sha256(text) {
  return hex(await crypto.subtle.digest("SHA-256", enc.encode(text)));
}

function safeEqual(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

const json = (data, status = 200, headers = {}) =>
  new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json", "cache-control": "no-store", ...headers },
  });

function getCookie(request, name) {
  const raw = request.headers.get("cookie") || "";
  for (const part of raw.split(";")) {
    const [k, ...v] = part.trim().split("=");
    if (k === name) return v.join("=");
  }
  return null;
}

const sessionCookie = (token, maxAge) =>
  `session=${token}; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=${maxAge}`;

async function createSession(env, userId) {
  const bytes = crypto.getRandomValues(new Uint8Array(32));
  const token = hex(bytes);
  const expires = Math.floor(Date.now() / 1000) + SESSION_SECONDS;
  await env.DB.prepare("INSERT INTO sessions (token_hash, user_id, expires_at) VALUES (?, ?, ?)")
    .bind(await sha256(token), userId, expires)
    .run();
  return token;
}

async function currentUser(request, env) {
  const token = getCookie(request, "session");
  if (!token) return null;
  const now = Math.floor(Date.now() / 1000);
  const row = await env.DB.prepare(
    `SELECT u.id, u.display_name, u.banned_until FROM sessions s JOIN users u ON u.id = s.user_id
     WHERE s.token_hash = ? AND s.expires_at > ?`
  )
    .bind(await sha256(token), now)
    .first();
  if (row && row.banned_until > now) return null; // banned users are signed out
  return row;
}

async function readCreds(request) {
  let body;
  try {
    body = await request.json();
  } catch {
    return { error: "Invalid request." };
  }
  const username = String(body.username || "").trim();
  const password = String(body.password || "");
  return { username, password };
}

let schemaReady = false;
async function ensureSchema(env) {
  if (schemaReady) return;
  await env.DB.batch([
    env.DB.prepare(
      "CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, salt TEXT NOT NULL, hash TEXT NOT NULL, robux INTEGER DEFAULT 0, created_at INTEGER NOT NULL)"
    ),
    env.DB.prepare(
      "CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL, expires_at INTEGER NOT NULL)"
    ),
    env.DB.prepare("CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id)"),
    // Legacy single-project table (kept for compatibility)
    env.DB.prepare("CREATE TABLE IF NOT EXISTS studio_projects (user_id INTEGER PRIMARY KEY, project_json TEXT NOT NULL, updated_at INTEGER NOT NULL)"),
    // New multi-experience table
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS experiences (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL,
      name TEXT NOT NULL,
      description TEXT DEFAULT '',
      maturity TEXT DEFAULT 'Minimal',
      thumbnail TEXT DEFAULT '',
      project_json TEXT NOT NULL,
      is_published INTEGER DEFAULT 0,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    )`),
    env.DB.prepare("CREATE INDEX IF NOT EXISTS experiences_user ON experiences(user_id)"),
  ]);
  try { await env.DB.prepare("ALTER TABLE users ADD COLUMN robux INTEGER DEFAULT 0").run(); } catch(e) {}
  try { await env.DB.prepare("ALTER TABLE users ADD COLUMN is_admin INTEGER DEFAULT 0").run(); } catch(e) {}
  try { await env.DB.prepare("ALTER TABLE users ADD COLUMN banned_until INTEGER DEFAULT 0").run(); } catch(e) {}
  try { await env.DB.prepare("ALTER TABLE experiences ADD COLUMN visibility TEXT DEFAULT 'private'").run(); await env.DB.prepare("UPDATE experiences SET visibility = 'public' WHERE is_published = 1").run(); } catch(e) {}
  schemaReady = true;
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (!url.pathname.startsWith("/api/")) {
      return new Response(PAGE, {
        headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache" },
      });
    }

    // Basic CSRF defence for state-changing calls: same-origin only.
    if (request.method === "POST" || request.method === "PUT" || request.method === "DELETE") {
      const origin = request.headers.get("origin");
      if (origin && origin !== url.origin) return json({ error: "Bad origin." }, 403);
    }

    try {
      await ensureSchema(env);

      if (url.pathname === "/api/me" && request.method === "GET") {
        const user = await currentUser(request, env);
        if (!user) return json({ user: null });
        const full = await env.DB.prepare("SELECT display_name, robux, username, is_admin FROM users WHERE id = ?").bind(user.id).first();
        return json({ user: { name: full.display_name, robux: full.robux || 0, username: full.username, isAdmin: isAdm(env, full) } });
      }

      if (url.pathname === "/api/signup" && request.method === "POST") {
        const { username, password, error } = await readCreds(request);
        if (error) return json({ error }, 400);
        if (!/^[A-Za-z0-9_]{3,20}$/.test(username))
          return json({ error: "Username must be 3–20 letters, numbers or underscores." }, 400);
        if (password.length < 8 || password.length > 200)
          return json({ error: "Password must be at least 8 characters." }, 400);

        const salt = crypto.getRandomValues(new Uint8Array(16));
        const hash = await hashPassword(password, salt);
        try {
          const res = await env.DB.prepare(
            "INSERT INTO users (username, display_name, salt, hash, created_at) VALUES (?, ?, ?, ?, ?)"
          )
            .bind(username.toLowerCase(), username, hex(salt), hash, Math.floor(Date.now() / 1000))
            .run();
          const token = await createSession(env, res.meta.last_row_id);
          return json({ user: { name: username } }, 200, { "set-cookie": sessionCookie(token, SESSION_SECONDS) });
        } catch (e) {
          if (String(e).includes("UNIQUE")) return json({ error: "That username is taken." }, 409);
          throw e;
        }
      }

      if (url.pathname === "/api/login" && request.method === "POST") {
        const { username, password, error } = await readCreds(request);
        if (error) return json({ error }, 400);
        const row = await env.DB.prepare("SELECT id, display_name, salt, hash, banned_until FROM users WHERE username = ?")
          .bind(username.toLowerCase())
          .first();
        // Always do the hashing work so timing doesn't reveal whether the user exists.
        const saltBytes = row ? fromHex(row.salt) : new Uint8Array(16);
        const attempt = await hashPassword(password.slice(0, 200), saltBytes);
        if (!row || !safeEqual(attempt, row.hash)) return json({ error: "Wrong username or password." }, 401);
        const nowS = Math.floor(Date.now() / 1000);
        if (row.banned_until > nowS) {
          const left = row.banned_until - nowS;
          return json({ error: `You are banned. Time left: ${Math.floor(left / 3600)}h ${Math.floor((left % 3600) / 60)}m ${left % 60}s` }, 403);
        }
        const token = await createSession(env, row.id);
        return json({ user: { name: row.display_name } }, 200, { "set-cookie": sessionCookie(token, SESSION_SECONDS) });
      }

      // ---- Experiences API ----
      if (url.pathname === "/api/experiences" && request.method === "GET") {
        const user = await currentUser(request, env);
        if (!user) return json({ error: "Please log in first." }, 401);
        const publishedOnly = url.searchParams.get("published") === "1";
        const mine = url.searchParams.get("mine") === "1" || !publishedOnly;
        const cols = "e.visibility, e.id, e.name, e.description, e.maturity, e.thumbnail, e.is_published, e.created_at, e.updated_at, u.display_name AS creator";
        const q = `SELECT ${cols} FROM experiences e JOIN users u ON u.id = e.user_id WHERE ${mine ? "e.user_id = ?" : "1 = ?"}${publishedOnly && url.searchParams.get("mine") !== "1" ? " AND e.visibility = 'public'" : " AND e.visibility != 'deleted'"} ORDER BY e.updated_at DESC LIMIT 30`;
        const { results } = await env.DB.prepare(q).bind(mine ? user.id : 1).all();
        return json({ experiences: results || [] });
      }

      if (url.pathname === "/api/experiences" && request.method === "POST") {
        const user = await currentUser(request, env);
        if (!user) return json({ error: "Please log in first." }, 401);
        let body;
        try { body = await request.json(); } catch { return json({ error: "Invalid JSON." }, 400); }
        const name = String(body.name || "Untitled Experience").slice(0, 60);
        const description = String(body.description || "").slice(0, 500);
        const maturity = ["Minimal", "Mild", "Moderate", "Restricted"].includes(body.maturity) ? body.maturity : "Minimal";
        const thumbnail = String(body.thumbnail || "").slice(0, 300000); // base64 data URL
        const project = body.project && Array.isArray(body.project.parts) ? body.project : { name, parts: [] };
        if (project.parts.length > 500) return json({ error: "Too many parts (max 500)." }, 400);
        const now = Math.floor(Date.now() / 1000);
        const res = await env.DB.prepare(
          `INSERT INTO experiences (user_id, name, description, maturity, thumbnail, project_json, is_published, created_at, updated_at)
           VALUES (?, ?, ?, ?, ?, ?, 0, ?, ?)`
        ).bind(user.id, name, description, maturity, thumbnail, JSON.stringify(project), now, now).run();
        return json({ id: res.meta.last_row_id, name, description, maturity, thumbnail, is_published: 0 });
      }

      // /api/experiences/:id
      const expMatch = url.pathname.match(/^\/api\/experiences\/(\d+)$/);
      if (expMatch) {
        const expId = Number(expMatch[1]);
        const user = await currentUser(request, env);
        if (!user) return json({ error: "Please log in first." }, 401);

        if (request.method === "GET") {
          const row = await env.DB.prepare(
            "SELECT e.id, e.user_id, e.name, e.description, e.maturity, e.thumbnail, e.project_json, e.is_published, e.visibility, e.created_at, e.updated_at, u.display_name AS creator FROM experiences e JOIN users u ON u.id = e.user_id WHERE e.id = ? AND (e.user_id = ? OR e.visibility IN ('public','unlisted'))"
          ).bind(expId, user.id).first();
          if (!row) return json({ error: "Experience not found." }, 404);
          return json({
            id: row.id,
            visibility: row.visibility,
            name: row.name,
            description: row.description,
            maturity: row.maturity,
            thumbnail: row.thumbnail,
            project: JSON.parse(row.project_json),
            is_published: !!row.is_published,
            created_at: row.created_at,
            updated_at: row.updated_at,
            creator: row.creator,
            mine: row.user_id === user.id,
          });
        }

        if (request.method === "PUT") {
          let body;
          try { body = await request.json(); } catch { return json({ error: "Invalid JSON." }, 400); }
          const existing = await env.DB.prepare("SELECT id FROM experiences WHERE id = ? AND user_id = ?").bind(expId, user.id).first();
          if (!existing) return json({ error: "Experience not found." }, 404);

          const name = body.name !== undefined ? String(body.name).slice(0, 60) : null;
          const description = body.description !== undefined ? String(body.description).slice(0, 500) : null;
          const maturity = body.maturity && ["Minimal", "Mild", "Moderate", "Restricted"].includes(body.maturity) ? body.maturity : null;
          const thumbnail = body.thumbnail !== undefined ? String(body.thumbnail).slice(0, 300000) : null;
          let projectJson = null;
          if (body.project) {
            if (!Array.isArray(body.project.parts) || body.project.parts.length > 500)
              return json({ error: "Invalid project format." }, 400);
            projectJson = JSON.stringify({ name: String(body.project.name || name || "My Place").slice(0, 60), parts: body.project.parts, scripts: cleanScripts(body.project.scripts), insts: cleanInsts(body.project.insts) });
          }
          const now = Math.floor(Date.now() / 1000);
          // Build dynamic update
          const sets = ["updated_at = ?"];
          const binds = [now];
          const vis = ["public", "unlisted", "private", "deleted"].includes(body.visibility) ? body.visibility : null;
          if (vis) { sets.push("visibility = ?"); binds.push(vis); sets.push("is_published = ?"); binds.push(vis === "public" || vis === "unlisted" ? 1 : 0); }
          if (name !== null) { sets.push("name = ?"); binds.push(name); }
          if (description !== null) { sets.push("description = ?"); binds.push(description); }
          if (maturity !== null) { sets.push("maturity = ?"); binds.push(maturity); }
          if (thumbnail !== null) { sets.push("thumbnail = ?"); binds.push(thumbnail); }
          if (projectJson !== null) { sets.push("project_json = ?"); binds.push(projectJson); }
          binds.push(expId, user.id);
          await env.DB.prepare(`UPDATE experiences SET ${sets.join(", ")} WHERE id = ? AND user_id = ?`).bind(...binds).run();
          return json({ ok: true });
        }

        if (request.method === "DELETE") {
          const r = await env.DB.prepare("DELETE FROM experiences WHERE id = ? AND user_id = ?").bind(expId, user.id).run();
          if (r.meta.changes === 0) return json({ error: "Experience not found." }, 404);
          return json({ ok: true });
        }
      }

      // Publish
      const pubMatch = url.pathname.match(/^\/api\/experiences\/(\d+)\/publish$/);
      if (pubMatch && request.method === "POST") {
        const expId = Number(pubMatch[1]);
        const user = await currentUser(request, env);
        if (!user) return json({ error: "Please log in first." }, 401);
        let body = {};
        try { body = await request.json(); } catch {}
        const name = body.name ? String(body.name).slice(0, 60) : null;
        const description = body.description !== undefined ? String(body.description).slice(0, 500) : null;
        const maturity = body.maturity && ["Minimal", "Mild", "Moderate", "Restricted"].includes(body.maturity) ? body.maturity : null;
        const thumbnail = body.thumbnail !== undefined ? String(body.thumbnail).slice(0, 300000) : null;
        const now = Math.floor(Date.now() / 1000);
        const sets = ["is_published = 1", "updated_at = ?", "visibility = ?"];
        const binds = [now, ["public", "unlisted", "private"].includes(body.visibility) ? body.visibility : "public"];
        if (body.project && Array.isArray(body.project.parts) && body.project.parts.length <= 500) {
          sets.push("project_json = ?");
          binds.push(JSON.stringify({ name: name || "My Place", parts: body.project.parts, scripts: cleanScripts(body.project.scripts), insts: cleanInsts(body.project.insts) }));
        }
        if (name) { sets.push("name = ?"); binds.push(name); }
        if (description !== null) { sets.push("description = ?"); binds.push(description); }
        if (maturity) { sets.push("maturity = ?"); binds.push(maturity); }
        if (thumbnail !== null) { sets.push("thumbnail = ?"); binds.push(thumbnail); }
        binds.push(expId, user.id);
        const r = await env.DB.prepare(`UPDATE experiences SET ${sets.join(", ")} WHERE id = ? AND user_id = ?`).bind(...binds).run();
        if (r.meta.changes === 0) return json({ error: "Experience not found." }, 404);
        return json({ ok: true, published: true });
      }

      // Legacy studio-project (still works for simple save/load)
      if (url.pathname === "/api/studio-project" && (request.method === "GET" || request.method === "POST")) {
        const user = await currentUser(request, env);
        if (!user) return json({ error: "Please log in first." }, 401);
        if (request.method === "GET") {
          const row = await env.DB.prepare("SELECT project_json, updated_at FROM studio_projects WHERE user_id = ?").bind(user.id).first();
          return json({ project: row ? JSON.parse(row.project_json) : null, updatedAt: row ? row.updated_at : null });
        }
        const raw = await request.text();
        if (raw.length > 150000) return json({ error: "Project is too large (150 KB maximum)." }, 413);
        let body;
        try { body = JSON.parse(raw); } catch { return json({ error: "Invalid project data." }, 400); }
        if (!body || !Array.isArray(body.parts) || body.parts.length > 500) return json({ error: "Invalid project format." }, 400);
        const project = JSON.stringify({ name: String(body.name || "My Place").slice(0, 60), parts: body.parts });
        const updatedAt = Math.floor(Date.now() / 1000);
        await env.DB.prepare("INSERT INTO studio_projects (user_id, project_json, updated_at) VALUES (?, ?, ?) ON CONFLICT(user_id) DO UPDATE SET project_json = excluded.project_json, updated_at = excluded.updated_at").bind(user.id, project, updatedAt).run();
        return json({ ok: true, updatedAt });
      }

      
      // Admin: only username "roblox" can manage robux
      if (url.pathname === "/api/admin/robux" && request.method === "POST") {
        const user = await currentUser(request, env);
        if (!user) return json({ error: "Please log in first." }, 401);
        const me = await env.DB.prepare("SELECT username, is_admin FROM users WHERE id = ?").bind(user.id).first();
        if (!me || !(isAdm(env, me))) return json({ error: "Admins only." }, 403);
        let body;
        try { body = await request.json(); } catch { return json({ error: "Invalid JSON." }, 400); }
        const target = String(body.username || "").trim().toLowerCase();
        const amount = Number(body.amount);
        const action = body.action === "remove" ? "remove" : "add";
        if (!target || !Number.isFinite(amount) || amount <= 0 || amount > 100000000) return json({ error: "Invalid username or amount." }, 400);
        const row = await env.DB.prepare("SELECT id, robux FROM users WHERE username = ?").bind(target).first();
        if (!row) return json({ error: "User not found." }, 404);
        let next = (row.robux || 0) + (action === "add" ? amount : -amount);
        if (next < 0) next = 0;
        await env.DB.prepare("UPDATE users SET robux = ? WHERE id = ?").bind(next, row.id).run();
        return json({ ok: true, username: target, robux: next });
      }

      // Admin: ban / unban and give / revoke admin
      if ((url.pathname === "/api/admin/ban" || url.pathname === "/api/admin/admin") && request.method === "POST") {
        const user = await currentUser(request, env);
        if (!user) return json({ error: "Please log in first." }, 401);
        const me = await env.DB.prepare("SELECT username, is_admin FROM users WHERE id = ?").bind(user.id).first();
        if (!me || !(isAdm(env, me))) return json({ error: "Admins only." }, 403);
        let body;
        try { body = await request.json(); } catch { return json({ error: "Invalid JSON." }, 400); }
        const target = String(body.username || "").trim().toLowerCase();
        const row = await env.DB.prepare("SELECT id, username FROM users WHERE username = ?").bind(target).first();
        if (!row) return json({ error: "User not found." }, 404);
        if (row.username === "roblox") return json({ error: "The Roblox account can't be changed." }, 403);
        if (url.pathname === "/api/admin/ban") {
          if (body.action === "unban") {
            await env.DB.prepare("UPDATE users SET banned_until = 0 WHERE id = ?").bind(row.id).run();
            return json({ ok: true, username: target, banned: false });
          }
          const secs = nn(body.hours) * 3600 + nn(body.minutes) * 60 + nn(body.seconds);
          if (!(secs > 0) || secs > 315360000) return json({ error: "Enter a ban time (HH / MM / SS)." }, 400);
          await env.DB.prepare("UPDATE users SET banned_until = ? WHERE id = ?").bind(Math.floor(Date.now() / 1000) + secs, row.id).run();
          await env.DB.prepare("DELETE FROM sessions WHERE user_id = ?").bind(row.id).run();
          return json({ ok: true, username: target, seconds: secs });
        }
        const make = body.action === "revoke" ? 0 : 1;
        await env.DB.prepare("UPDATE users SET is_admin = ? WHERE id = ?").bind(make, row.id).run();
        return json({ ok: true, username: target, isAdmin: !!make });
      }

      if (url.pathname === "/api/robux" && request.method === "GET") {
        const user = await currentUser(request, env);
        if (!user) return json({ error: "Please log in first." }, 401);
        const row = await env.DB.prepare("SELECT robux FROM users WHERE id = ?").bind(user.id).first();
        return json({ robux: row?.robux || 0 });
      }

      // Simple global chat
      if (url.pathname === "/api/chat" && request.method === "GET") {
        const user = await currentUser(request, env);
        if (!user) return json({ error: "Please log in first." }, 401);
        await env.DB.prepare("CREATE TABLE IF NOT EXISTS chat_messages (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, username TEXT NOT NULL, body TEXT NOT NULL, created_at INTEGER NOT NULL)").run();
        const { results } = await env.DB.prepare("SELECT username, body, created_at FROM chat_messages ORDER BY id DESC LIMIT 50").all();
        return json({ messages: (results || []).reverse() });
      }
      if (url.pathname === "/api/chat" && request.method === "POST") {
        const user = await currentUser(request, env);
        if (!user) return json({ error: "Please log in first." }, 401);
        let body;
        try { body = await request.json(); } catch { return json({ error: "Invalid JSON." }, 400); }
        const text = String(body.message || body.body || "").trim().slice(0, 200);
        if (!text) return json({ error: "Empty message." }, 400);
        await env.DB.prepare("CREATE TABLE IF NOT EXISTS chat_messages (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, username TEXT NOT NULL, body TEXT NOT NULL, created_at INTEGER NOT NULL)").run();
        const uname = (await env.DB.prepare("SELECT display_name FROM users WHERE id = ?").bind(user.id).first()).display_name;
        await env.DB.prepare("INSERT INTO chat_messages (user_id, username, body, created_at) VALUES (?, ?, ?, ?)").bind(user.id, uname, text, Math.floor(Date.now()/1000)).run();
        return json({ ok: true });
      }


      if (url.pathname === "/api/logout" && request.method === "POST") {
        const token = getCookie(request, "session");
        if (token) await env.DB.prepare("DELETE FROM sessions WHERE token_hash = ?").bind(await sha256(token)).run();
        return json({ ok: true }, 200, { "set-cookie": sessionCookie("", 0) });
      }

      return json({ error: "Not found." }, 404);
    } catch (e) {
      console.error(e);
      return json({ error: "Server error. Please try again." }, 500);
    }
  },
};

